#!/usr/bin/env bash
# Renders BENCHMARKS.md from the raw benchmark outputs in /tmp/bench/.
# Also refreshes the comparison table in README.md between the
# <!-- BENCHMARKS:START --> and <!-- BENCHMARKS:END --> markers.
# Called by .github/workflows/benchmark.yml after the suite runs.
set -euo pipefail

RUNTIME=/tmp/bench/runtime.txt
TUNING=/tmp/bench/tuning.txt
WORKLOAD=/tmp/bench/workload.txt
COMPARISON=/tmp/bench/comparison.txt
OUT=BENCHMARKS.md
README=README.md

DATE="${RUN_DATE:-$(date -u +%Y-%m-%dT%H:%M:%SZ)}"
SHORT_SHA="${COMMIT_SHA:0:7}"

headline() {
  grep -h "• Raw Worker IPC Round-Trip\|• End-to-End Runtime Task Cost\|• Scheduler + Graph Overhead\|• Worker Fleet Event Loop Lag\|• RSS Heap Memory\|• V8/JSC Heap Used\|• 25,000 Tasks Completed in\|• Peak RSS Memory\|• Settled Cooldown RSS" \
    "$RUNTIME" "$TUNING" "$WORKLOAD" 2>/dev/null | sort -u || true
}

md_table() {
  grep -h "^|" "$1" 2>/dev/null || true
}

comparison_table() {
  awk '/^\| Framework/{flag=1} flag' "$COMPARISON" 2>/dev/null | grep "^|" || true
}

details() {
  local title="$1" file="$2"
  {
    echo "<details>"
    echo "<summary>$title (full log)</summary>"
    echo ""
    echo '```'
    cat "$file" 2>/dev/null || echo "(log unavailable)"
    echo '```'
    echo "</details>"
  }
}

{
  echo "# Yatta Benchmarks"
  echo ""
  echo "> Last run: \`$DATE\` · commit [\`$SHORT_SHA\`](https://github.com/psrockstar098/yatta.js/commit/$COMMIT_SHA) · \`ubuntu-latest\`, Bun 1.4.2"
  echo ">"
  echo "> Benchmarks run on every push to \`main\` and weekly via GitHub Actions."
  echo "> Numbers come from shared CI runners, so treat them as relative — the trend matters more than any single value."
  echo ""
  echo "## Headline metrics"
  echo ""
  echo '```'
  METRICS="$(headline)"
  if [ -n "$METRICS" ]; then
    echo "$METRICS"
  else
    echo "(benchmark output unavailable — see workflow logs)"
  fi
  echo '```'
  echo ""
  echo "## Framework comparison"
  echo ""
  echo "Head-to-head HTTP throughput: one \`GET /json\` route per framework,"
  echo "20,000 requests at 100 concurrent connections (keep-alive)."
  echo "Each framework is measured in its own process, three times, and the median is"
  echo "reported. \`Spread\` is how far apart a framework's own runs were — if two"
  echo "frameworks are within each other's spread, the data does not separate them."
  echo ""
  CMP="$(comparison_table)"
  if [ -n "$CMP" ]; then echo "$CMP"; else echo "_No comparison data captured._"; fi
  echo ""
  echo "## Throughput ladder (worker runtime)"
  echo ""
  echo "Fast-ping tasks through the worker fleet, 10 → 10,000 concurrent:"
  echo ""
  TABLES="$(md_table "$RUNTIME" | head -10)"
  if [ -n "$TABLES" ]; then echo "$TABLES"; else echo "_No table data captured._"; fi
  echo ""
  echo "## Real-world workloads"
  echo ""
  echo "JSON payload transformation and micro-compute tasks:"
  echo ""
  TABLES="$(md_table "$WORKLOAD" | head -30)"
  if [ -n "$TABLES" ]; then echo "$TABLES"; else echo "_No table data captured._"; fi
  echo ""
  echo "## Full logs"
  echo ""
  details "Worker runtime deep profile" "$RUNTIME"
  echo ""
  details "Topology & tail tuning" "$TUNING"
  echo ""
  details "Comprehensive workload benchmark" "$WORKLOAD"
  echo ""
  details "Framework comparison" "$COMPARISON"
  echo ""
  echo "---"
  echo "_Generated by [\`benchmark.yml\`](.github/workflows/benchmark.yml)._"
} > "$OUT"

echo "Wrote $OUT"

if [ -f "$README" ] && grep -q "BENCHMARKS:START" "$README"; then
  CMP="$(comparison_table)"
  if [ -n "$CMP" ]; then
    export CMP_TABLE="$CMP"
    python3 - "$README" <<'PYEOF'
import os, re, sys
path = sys.argv[1]
table = os.environ["CMP_TABLE"]
s = open(path).read()
s = re.sub(
    r"<!-- BENCHMARKS:START -->.*?<!-- BENCHMARKS:END -->",
    "<!-- BENCHMARKS:START -->\n" + table + "\n<!-- BENCHMARKS:END -->",
    s,
    flags=re.DOTALL,
)
open(path, "w").write(s)
PYEOF
    echo "Refreshed README benchmark table"
  else
    echo "Skipped README refresh (no comparison data)"
  fi
fi

# Build benchmarks.json for the website (yatta.js.org/benchmarks).
python3 - <<'PYEOF'
import json, os

out = "benchmarks.json"
date = os.environ.get("RUN_DATE") or __import__("datetime").datetime.now(__import__("datetime").timezone.utc).isoformat()
sha = os.environ.get("COMMIT_SHA", "")
short = sha[:7] if sha else ""

data = {
    "generated_at": date,
    "commit": sha,
    "commit_short": short,
    "commit_url": f"https://github.com/psrockstar098/yatta.js/commit/{sha}" if sha else None,
    "runner": "ubuntu-latest",
    "runtime": "Bun 1.4.2",
    "comparison": None,
}

cmp_path = "/tmp/bench/comparison.json"
if os.path.exists(cmp_path):
    try:
        with open(cmp_path) as f:
            data["comparison"] = json.load(f)
    except Exception as e:
        print(f"Warning: could not parse comparison.json: {e}")

with open(out, "w") as f:
    json.dump(data, f, indent=2)
print(f"Wrote {out}")
PYEOF
